-- 单表（优化器常量评估 → Impossible WHERE → 0 行）
SELECT EXISTS (SELECT 1) AS ref0 FROM vp_s
WHERE (vp_s.c0) IN (IFNULL(0.7957106135922298, 'nK'));

SELECT DISTINCTROW c0 AS ref0
FROM s
WHERE c1 IN (COALESCE(0.36047097332362965, NULL, NULL, 275915752));

SELECT DISTINCT s.c0 AS ref0
FROM s
GROUP BY s.c0;

SELECT CAST(LEAST('z', '_ejEZpA(1', '2090248689', c0) AS SIGNED) AS ref0
FROM s
ORDER BY vp_rowid;

-- Single: 覆盖索引 → (-2,0), (-1,NULL) ✓
SELECT (- vp_rowid) AS ref0, ('x') = (IFNULL(NULL, c1) XOR 0) AS ref1
FROM src GROUP BY (- vp_rowid), ('x') = (IFNULL(NULL, c1) XOR 0);

-- 正确基线：空表聚合，返回 NULL
SELECT MIN(EXISTS(SELECT 1 WHERE FALSE)) AS v
FROM s;

-- 单表查询（covering index → CAST 正确）
SELECT DISTINCTROW MAX(DISTINCT vp_s.vp_rowid) AS ref0 FROM vp_s
WHERE CAST(IFNULL(vp_s.c0, vp_s.c1) AS SIGNED);

-- 单表查询（covering index → IFNULL 正确 → c0=0 的行通过）
SELECT COUNT(*) FROM vp_s
WHERE 1 NOT IN (IFNULL(NULL, vp_s.c0), CAST('abc' AS SIGNED));

SELECT COUNT(*) AS cnt
FROM vp_source
WHERE NOT (IFNULL(0.5, 0) NOT IN (id));
